package com.nx.android

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.nio.file.Files
import java.util.Base64

/**
 * The tar reader, on the archives the app unpacks: the rootfs (GNU format, long names, links) and a pax archive
 * whose file size is only in the pax header.
 */
class TarTest {

    @Test
    fun gnuArchive() {
        val dir = Files.createTempDirectory("nx2a-tar").toFile()
        val tar = Base64.getDecoder().decode(GNU)
        Tar.unpack(tar.inputStream(), dir)

        assertEquals("hello world\n", File(dir, "dir/small.txt").readText())
        assertEquals(1000L, File(dir, "dir/thousand.bin").length())
        assertEquals("abc", File(dir, "dir/deep/deep/deep/deep/deep/deep/deep/deep/deep/deep/deep/deep/name.txt").readText())
        assertTrue("the symbolic link", Files.isSymbolicLink(File(dir, "dir/link").toPath()))
        assertEquals("small.txt", Files.readSymbolicLink(File(dir, "dir/link").toPath()).toString())
        assertEquals("hello world\n", File(dir, "dir/hard").readText())
        assertTrue("the program's permission bits", File(dir, "dir/program").canExecute())
        assertTrue("a plain file is not executable", !File(dir, "dir/small.txt").canExecute())
    }

    @Test
    fun paxArchive() {
        val dir = Files.createTempDirectory("nx2a-tar").toFile()
        val tar = Base64.getDecoder().decode(PAX)
        Tar.unpack(tar.inputStream(), dir)
        // the long path is in a pax header, not in the ustar header
        assertEquals("paxxy", File(dir, "pax/deep/deep/deep/deep/deep/deep/deep/deep/deep/deep/deep/deep/deep/deep/file.txt").readText())
        assertEquals("abc", File(dir, "pax/small.txt").readText())
    }

    companion object {
        // a GNU archive: a folder, a small file, a file of 1000 bytes (the padding), a long name, a symbolic link
        // and a hard link
        private const val GNU = ""
        // a pax archive: the size of the file is in the pax header, not in the ustar header
        private const val PAX = ""
    }
}
